"""Text-to-SQL harness with execution-grounded verification and one repair call.

Contract (fixed): solve(task, env) -> {"sql": str}
  task  {"id", "db_id", "question", "hint"}      (hint is BIRD's evidence; "" for Spider)
  env.chat(messages, max_tokens=None) -> str     policy call (capped per task: env.max_calls)
  env.schema(db_id) -> str                       CREATE statements of the database
  env.execute(sql, max_rows=20) -> dict          read-only run: {ok, columns, rows, n_rows, error}
  env.descriptions(db_id) -> str                 column descriptions if the dataset ships them, else ""
  env.prompt(name) -> str                        text of a file in this harness
  env.config -> dict                             parsed config.json

Flow: draft -> execute -> (if broken/empty) probe literals & join keys -> repair call.
All probing is generic schema/value inspection; nothing is task specific.
"""

import re

SQL_BLOCK = re.compile(r"```(?:sql|sqlite)?\s*(.*?)```", re.S | re.I)
STR_LIT = re.compile(r"'((?:[^']|'')*)'")
IDENT = r'[A-Za-z_][A-Za-z0-9_]*'
QUAL_COL = re.compile(r'\b(' + IDENT + r')\.(' + IDENT + r')\b')
JOIN_ON = re.compile(
    r'\bON\s+(' + IDENT + r')\.(' + IDENT + r')\s*=\s*(' + IDENT + r')\.(' + IDENT + r')',
    re.I,
)
FROM_JOIN = re.compile(r'\b(?:FROM|JOIN)\s+("?' + IDENT + r'"?)(?:\s+(?:AS\s+)?("?' + IDENT + r'"))?', re.I)
KEYWORDS = {
    'where', 'on', 'join', 'inner', 'left', 'right', 'full', 'outer', 'cross', 'natural',
    'group', 'order', 'limit', 'having', 'union', 'intersect', 'except', 'as', 'and', 'or',
    'not', 'select', 'set', 'using', 'values', 'when', 'then', 'else', 'end', 'distinct',
}


def extract_sql(text):
    blocks = [b.strip() for b in SQL_BLOCK.findall(text or "") if b.strip()]
    if blocks:
        return blocks[-1].rstrip(";").strip()
    return (text or "").strip().rstrip(";").strip()


def _q(value):
    return "'" + str(value).replace("'", "''") + "'"


def _run(env, sql, max_rows=5):
    try:
        return env.execute(sql, max_rows=max_rows)
    except Exception as exc:  # never let diagnostics kill the task
        return {"ok": False, "columns": [], "rows": [], "n_rows": 0, "error": str(exc)}


def _fmt(res, limit=5):
    if not res.get("ok"):
        return "ERROR: %s" % str(res.get("error"))[:200]
    rows = res.get("rows") or []
    body = "; ".join(str(list(r))[:160] for r in rows[:limit])
    return "%d row(s)%s" % (res.get("n_rows", len(rows)), (": " + body) if body else "")


def _alias_map(sql):
    """alias/table-name -> real table name, from FROM/JOIN clauses."""
    mapping = {}
    for m in FROM_JOIN.finditer(sql):
        table = m.group(1).strip('"')
        alias = (m.group(2) or "").strip('"')
        if alias and alias.lower() in KEYWORDS:
            alias = ""
        mapping[table.lower()] = table
        if alias:
            mapping[alias.lower()] = table
    return mapping


def _resolve(alias, col, amap):
    table = amap.get(alias.lower())
    if table:
        return table, col
    for t in amap.values():
        return t, col
    return None, col


def _probe_literal(env, sql, amap, lit):
    """Find how the value actually appears in the columns the query filters on."""
    refs = QUAL_COL.findall(sql)
    targets = []
    for a, c in refs:
        t, cc = _resolve(a, c, amap)
        if t and (t, cc) not in targets:
            targets.append((t, cc))
    if not targets:
        for t in dict.fromkeys(amap.values()):
            targets.append((t, None))
    core = lit.strip()
    if not core:
        return []
    pat = "%" + core.replace("%", "") + "%"
    notes = []
    for table, col in targets[:4]:
        if col:
            cols = [col]
        else:
            info = _run(env, 'SELECT * FROM "%s" LIMIT 1' % table, max_rows=1)
            cols = [c for c in (info.get("columns") or [])][:12]
        for c in cols:
            expr = 'CAST("%s" AS TEXT)' % c
            exact = _run(env, 'SELECT COUNT(*) FROM "%s" WHERE %s = %s' % (table, expr, _q(lit)), 1)
            loose = _run(env, 'SELECT COUNT(*) FROM "%s" WHERE %s LIKE %s' % (table, expr, _q(pat)), 1)
            n_exact = exact["rows"][0][0] if exact.get("ok") and exact.get("rows") else None
            n_loose = loose["rows"][0][0] if loose.get("ok") and loose.get("rows") else None
            if not n_loose:
                continue
            sample = _run(
                env,
                'SELECT DISTINCT "%s" FROM "%s" WHERE %s LIKE %s LIMIT 5' % (c, table, expr, _q(pat)),
                5,
            )
            vals = [r[0] for r in (sample.get("rows") or [])]
            notes.append(
                "value %s: %s.%s has %s exact matches but %s rows containing %r; stored examples: %s"
                % (_q(lit), table, c, n_exact, n_loose, core, str(vals)[:220])
            )
            break
        if len(notes) >= 3:
            break
    return notes


def _probe_join(env, sql, amap):
    notes = []
    seen = set()
    for a1, c1, a2, c2 in JOIN_ON.findall(sql):
        t1, k1 = _resolve(a1, c1, amap)
        t2, k2 = _resolve(a2, c2, amap)
        if not t1 or not t2 or t1 == t2:
            continue
        key = (t1, k1, t2, k2)
        if key in seen:
            continue
        seen.add(key)
        overlap = _run(
            env,
            'SELECT COUNT(*) FROM "%s" a JOIN "%s" b ON a."%s" = b."%s"' % (t1, t2, k1, k2),
            1,
        )
        n = overlap["rows"][0][0] if overlap.get("ok") and overlap.get("rows") else None
        if n:
            continue
        s1 = _run(env, 'SELECT DISTINCT "%s" FROM "%s" LIMIT 5' % (k1, t1), 5)
        s2 = _run(env, 'SELECT DISTINCT "%s" FROM "%s" LIMIT 5' % (k2, t2), 5)
        notes.append(
            "join %s.%s = %s.%s produces %s matching rows (likely wrong key or format). "
            "%s.%s samples: %s | %s.%s samples: %s"
            % (t1, k1, t2, k2, n, t1, k1, str([r[0] for r in s1.get("rows") or []])[:150],
               t2, k2, str([r[0] for r in s2.get("rows") or []])[:150])
        )
        if len(notes) >= 3:
            break
    return notes


def diagnose(env, sql, result):
    """Generic, read-only evidence about why a draft fails or returns nothing."""
    notes = []
    if not result.get("ok"):
        notes.append("The draft failed to execute: %s" % str(result.get("error"))[:300])
        return notes
    if result.get("n_rows", 0) > 0:
        return notes
    amap = _alias_map(sql)
    if not amap:
        return notes
    notes.append("The draft executed but returned ZERO rows.")
    lits = list(dict.fromkeys(STR_LIT.findall(sql)))
    for lit in lits[:3]:
        if "%" in lit or "_" in lit:
            continue
        notes.extend(_probe_literal(env, sql, amap, lit))
    notes.extend(_probe_join(env, sql, amap))
    if len(notes) == 1:
        for t in dict.fromkeys(amap.values()):
            cnt = _run(env, 'SELECT COUNT(*) FROM "%s"' % t, 1)
            if cnt.get("ok") and cnt.get("rows"):
                notes.append("row count of %s: %s" % (t, cnt["rows"][0][0]))
    return notes


REPAIR_RULES = (
    "Repair rules:\n"
    "- Use the evidence above. Match stored values exactly (case, spacing, punctuation); prefer "
    "trim(col) = 'value' or col LIKE '%value%' over an exact match that finds nothing.\n"
    "- If a join key yields no overlap, join on the correct key/column shown by the samples.\n"
    "- A relation/friendship/link table may store each pair in one direction only: consider both "
    "columns (UNION or OR) when asking who participates.\n"
    "- Keep the question's intent, the requested columns and any ordering/LIMIT; do not add filters "
    "the question did not ask for.\n"
    "Return the corrected query in a single ```sql code block."
)


def solve(task, env):
    cfg = env.config or {}
    max_tokens = cfg.get("max_tokens", 800)
    schema = env.schema(task["db_id"])
    user = "Database: %s\n\nSchema:\n%s\n\nQuestion: %s" % (task["db_id"], schema, task["question"])
    desc = ""
    try:
        desc = env.descriptions(task["db_id"]) or ""
    except Exception:
        desc = ""
    if desc.strip():
        user += "\n\nColumn descriptions:\n" + desc.strip()[:2000]
    if task.get("hint"):
        user += "\nHint: %s" % task["hint"]

    messages = [
        {"role": "system", "content": env.prompt("system_prompt.md")},
        {"role": "user", "content": user},
    ]
    reply = env.chat(messages, max_tokens=max_tokens)
    sql = extract_sql(reply)

    if not cfg.get("verify", True):
        return {"sql": sql}

    result = _run(env, sql, max_rows=5)
    needs_repair = (not result.get("ok")) or result.get("n_rows", 0) == 0
    if not needs_repair or not sql:
        return {"sql": sql}

    notes = diagnose(env, sql, result)
    if not notes:
        return {"sql": sql}

    feedback = (
        "Your draft query was:\n```sql\n%s\n```\n\nExecution feedback:\n%s\n\n%s"
        % (sql, "\n".join("- " + n for n in notes), REPAIR_RULES)
    )
    messages = messages + [
        {"role": "assistant", "content": reply},
        {"role": "user", "content": feedback},
    ]
    try:
        reply2 = env.chat(messages, max_tokens=max_tokens)
    except Exception:
        return {"sql": sql}
    sql2 = extract_sql(reply2)
    if not sql2:
        return {"sql": sql}
    res2 = _run(env, sql2, max_rows=5)
    if res2.get("ok") and (res2.get("n_rows", 0) > 0 or not result.get("ok")):
        return {"sql": sql2}
    if res2.get("ok") and not result.get("ok"):
        return {"sql": sql2}
    return {"sql": sql2 if res2.get("ok") else sql}

